declare(strict_types=1); require_once __DIR__.'/../bootstrap.php'; Auth::requireRole('admin');$rows=db()->query('SELECT id,reference,amount,currency,status,gateway,created_at FROM payments ORDER BY id DESC LIMIT 200')->fetchAll();$active='payments';$pageTitle='Payments';$pageDescription='Gateway transactions and payment verification status';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payments · DogoFlow Admin</title><link rel="icon" href="<?=url('/assets/images/favicon-32.png')?>"><link rel="stylesheet" href="<?=url('/assets/css/app.css')?>">
    <link rel="stylesheet" href="<?=url('/assets/css/admin.css')?>"></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php'; ?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php'; ?><main class="admin-content"><div class="page-heading"><div><h1>Payments</h1><p>Verified gateway payments recorded by the platform.</p></div></div><article class="panel-df"><div class="table-wrap-df"><table class="table-df"><thead><tr><th>Reference</th><th>Amount</th><th>Currency</th><th>Status</th><th>Gateway</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['reference'])?></strong></td><td><strong><?=number_format((float)$r['amount'],2)?></strong></td><td><?=e($r['currency'])?></td><td><span class="badge-df <?=$r['status']==='success'?'success':($r['status']==='failed'?'danger':'warning')?>"><?=e($r['status'])?></span></td><td><?=e($r['gateway'])?></td><td><?=e(date('d M Y · H:i',strtotime($r['created_at'])))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6"><div class="empty-df">No payment records yet.</div></td></tr><?php endif;?></tbody></table></div></article></main></section></body></html>
